<template>
  <div id="ht-wrap">
    <div id="ht-left">
      <div id="ht-icon">{{ currentStep.icon }}</div>
      <h1>{{ currentStep.leftTitle }}</h1>
      <p>{{ currentStep.leftDesc }}</p>
      <div id="ht-dots">
        <span
          v-for="(s, i) in steps"
          :key="i"
          :class="['ht-dot', { active: i === current }]"
          @click="current = i"
        ></span>
      </div>
    </div>

    <div id="ht-right">
      <div id="ht-card">
        <div id="ht-img">
          <img :src="currentStep.img" :alt="currentStep.cardTitle" />
          <div v-if="!currentStep.img" class="ht-img-placeholder">
            <span>{{ currentStep.icon }}</span>
          </div>
        </div>
        <h2>{{ currentStep.cardTitle }}</h2>
        <div class="ht-tip">💡 {{ currentStep.tip }}</div>
        <p>{{ currentStep.cardDesc }}</p>
        <div id="ht-btn-row">
          <button class="ht-btn ht-prev" :disabled="current === 0" @click="prev">← Back</button>
          <span id="ht-counter">{{ current + 1 }} / {{ steps.length }}</span>
          <button class="ht-btn ht-next" @click="current === steps.length - 1 ? $router.push('/Schedule') : next()">
            {{ current === steps.length - 1 ? 'Done ✓' : 'Next →' }}
          </button>
        </div>
      </div>
    </div>
  </div>
</template>

<script>
export default {
  name: 'HowToUse',
  data() {
    return {
      current: 0,
      steps: [
        {
          icon: '📝',
          leftTitle: 'Create your account',
          leftDesc: 'Sign up with your email to get started. Click "Create a new one" on the login page.',
          cardTitle: 'Step 1 — Register or Login',
          tip: 'Use a real email address — disposable emails are not allowed.',
          cardDesc: 'On the login page, click "Create a new one" to register. Fill in your email and password. Already have an account? Just enter your credentials and click "Login Now".',
          img: 'data:image/png;base64,'
        },
        {
          icon: '🔐',
          leftTitle: 'Login to CoreTalk',
          leftDesc: 'Enter your credentials on the login screen to access the meeting platform.',
          cardTitle: 'Step 2 — Login Screen',
          tip: 'Forgot your password? Click the "Forgot Password: Click here" link at the bottom.',
          cardDesc: 'Enter your registered email address and password, then click "Login Now". You can also use the "OR" separator area for alternative login options. The login page has the same CoreTalk branding layout.',
          img: 'data:image/png;base64,'
        },
        {
          icon: '📅',
          leftTitle: 'Schedule Page — Your Home Base',
          leftDesc: 'After login you land here. Create a room or join one by pasting a Room ID.',
          cardTitle: 'Step 3 — Schedule / Home Page',
          tip: 'The Room ID is a long UUID like: 7683716f-154a-446d-873e-235674296036',
          cardDesc: 'To join an existing meeting: paste the Room ID (shared by the host) into the input field and click "Enter". To create your own room: click "Create your room" — a title input will appear. Fill it in and click again to launch your room.',
          img: 'data:image/png;base64,'
        },
        {
          icon: '🔗',
          leftTitle: 'Share your Meeting Link',
          leftDesc: 'Copy the Room ID from the URL bar and send it to participants.',
          cardTitle: 'Step 4 — Sharing the Room ID',
          tip: 'The Room ID is everything after /MeetingRoom/ in the URL.',
          cardDesc: 'Once inside the meeting room, look at your browser URL bar — it shows the full Room ID (e.g. /MeetingRoom/7683716f-154a-446d-873e-235674296036). Copy everything after /MeetingRoom/ and share it with others so they can paste it on the Schedule page to join.',
          img: 'data:image/png;base64,'
        },
        {
          icon: '🎛️',
          leftTitle: 'Control your meeting',
          leftDesc: 'Use the bottom controls to manage audio, video and screen sharing.',
          cardTitle: 'Step 5 — Meeting Controls',
          tip: 'Host controls like Mute All and End Meeting are only visible to the host.',
          cardDesc: 'Toggle your mic and camera using the control buttons at the bottom. Click Share Screen to present. Raise your hand to notify the host. Use the left tray for Silent Background, Recording, Fullscreen and Gmail Enact features.',
          img: ''
        },
        {
          icon: '💬',
          leftTitle: 'Chat and wrap up',
          leftDesc: 'Use live chat during the meeting. A summary page appears when you leave.',
          cardTitle: 'Step 6 — Chat and Ending',
          tip: 'Only the host can end the meeting for everyone. Others can leave individually.',
          cardDesc: 'Click the chat icon to open the live chat panel. Type messages visible to all participants. Live Captions show a real-time transcript. When done, click Leave — you will be taken to the Ending page where you can leave a review.',
          img: ''
        }
      ]
    };
  },
  computed: {
    currentStep() {
      return this.steps[this.current];
    }
  },
  methods: {
    next() { if (this.current < this.steps.length - 1) this.current++; },
    prev() { if (this.current > 0) this.current--; }
  }
};
</script>

